// Draws one person's history of one measure: the readings over time, the norm, the moments of the
// flight (start, today, landing) and the forecast line. Plain SVG, no outside packages, works offline.
// Code generated by Claude (Anthropic), an AI system.

const NS = 'http://www.w3.org/2000/svg';
const DAY = 24 * 60 * 60 * 1000;

function el(tag, attrs = {}, text) {
  const node = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) node.setAttribute(k, String(v));
  if (text !== undefined) node.textContent = text;
  return node;
}

const two = (n) => String(n).padStart(2, '0');
export const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export const fmtDate = (t) => { const d = new Date(t); return `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`; };
// Crew screens keep time in GMT, as on the ISS.
export const fmtGMT = (t) => { const d = new Date(t); return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${two(d.getUTCHours())}:${two(d.getUTCMinutes())} GMT`; };

// Clean tick values for an axis between lo and hi.
function ticks(lo, hi, count = 4) {
  const span = hi - lo || 1;
  const raw = span / count;
  const pow = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 2.5, 5, 10].map((k) => k * pow).find((s) => s >= raw) || raw;
  const out = [];
  for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) out.push(Number(v.toFixed(6)));
  return out;
}

// opts: { series: [{ name, color, points: [{ t, v, out }] }], band: { min, max } | null, lines: [{ v, label }],
//         mission: { launch, today, landing }, trend: { from, to, at } | null, fmt, ordinal: { 1: 'bad', ... } | null, label,
//         range: { from, to } | null  (only this period of time is shown) }
export function drawHistory(host, tip, opts) {
  host.replaceChildren();
  const range = opts.range || null;
  const inRange = (p) => !range || (p.t >= range.from && p.t <= range.to);
  const seriesAll = opts.series.map((s) => ({ ...s, points: s.points.filter(inRange) }));
  const all = seriesAll.flatMap((s) => s.points);
  if (all.length === 0) {
    host.append(Object.assign(document.createElement('p'), { className: 'empty', textContent: range ? 'No readings in this period.' : 'No readings of this measure for this person yet.' }));
    return;
  }
  const outText = opts.outText === undefined ? 'outside the normal range' : opts.outText;
  const W = Math.max(300, Math.round(host.getBoundingClientRect().width) || 640);
  const H = W < 600 ? 270 : 330;
  const m = { l: 56, r: 16, t: 40, b: 34 };
  const launch = new Date(opts.mission.launch).getTime();
  const today = new Date(opts.mission.today).getTime();
  const landing = new Date(opts.mission.landing).getTime();
  const t0 = range ? range.from : Math.min(...all.map((p) => p.t), launch - 7 * DAY);
  const t1 = range ? range.to : Math.max(...all.map((p) => p.t), landing + 10 * DAY);
  const trendEnd = Math.min(landing, t1);
  const values = all.map((p) => p.v);
  if (opts.band) { if (opts.band.min !== null && opts.band.min !== undefined) values.push(opts.band.min); if (opts.band.max !== null && opts.band.max !== undefined) values.push(opts.band.max); }
  for (const l of opts.lines || []) values.push(l.v);
  if (opts.trend && trendEnd > t0) values.push(opts.trend.at(trendEnd));
  let lo = Math.min(...values);
  let hi = Math.max(...values);
  if (opts.ordinal) { lo = 0.5; hi = Math.max(...Object.keys(opts.ordinal).map(Number)) + 0.5; }
  const pad = (hi - lo) * 0.08 || 1;
  if (!opts.ordinal) { lo -= pad; hi += pad; }
  const x = (t) => m.l + ((t - t0) / (t1 - t0)) * (W - m.l - m.r);
  const y = (v) => m.t + (1 - (v - lo) / (hi - lo)) * (H - m.t - m.b);

  const svg = el('svg', { viewBox: `0 0 ${W} ${H}`, width: '100%', height: H, role: 'img', 'aria-label': opts.label || '' });

  // Norm band: a quiet wash between the norm's borders.
  if (opts.band) {
    const top = opts.band.max !== null && opts.band.max !== undefined ? y(Math.min(opts.band.max, hi)) : m.t;
    const bottom = opts.band.min !== null && opts.band.min !== undefined ? y(Math.max(opts.band.min, lo)) : H - m.b;
    if (bottom > top) svg.append(el('rect', { x: m.l, y: top, width: W - m.l - m.r, height: bottom - top, class: 'norm-band' }));
  }

  // Grid and the value axis.
  const yt = opts.ordinal ? Object.keys(opts.ordinal).map(Number) : ticks(lo, hi);
  for (const v of yt) {
    svg.append(el('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), class: 'grid' }));
    svg.append(el('text', { x: m.l - 8, y: y(v) + 4, class: 'tick', 'text-anchor': 'end' }, opts.ordinal ? opts.ordinal[v] : opts.fmt(v)));
  }
  svg.append(el('line', { x1: m.l, x2: W - m.r, y1: H - m.b, y2: H - m.b, class: 'axis' }));
  if (opts.unit) svg.append(el('text', { x: 2, y: 12, class: 'tick unit' }, opts.unit));

  // Border lines (for example "limit 600"). Their names are drawn later, on top of everything.
  for (const l of opts.lines || []) svg.append(el('line', { x1: m.l, x2: W - m.r, y1: y(l.v), y2: y(l.v), class: 'limit' }));

  // The moments of the flight, named on top and dated under the axis. When two moments are close,
  // the second name moves down a row and its date is left out, so nothing overlaps.
  const dayMonth = (t) => { const d = new Date(t); return `${d.getDate()} ${MONTHS[d.getMonth()]}`; };
  let lastTop = -Infinity;
  let lastBottom = -Infinity;
  const shortFlight = landing - launch <= 7 * DAY;
  if (shortFlight && launch >= t0 && landing <= t1) {
    svg.append(el('rect', { x: x(launch), y: m.t, width: Math.max(2, x(landing) - x(launch)), height: H - m.t - m.b, class: 'flight-span' }));
    svg.append(el('text', { x: (x(launch) + x(landing)) / 2, y: m.t - 10, class: 'moment-label halo', 'text-anchor': 'middle' }, 'Flight'));
  }
  for (const [t, name, withYear] of (shortFlight ? [] : [[launch, 'Launch', true], [today, 'Today', false], [landing, 'Landing', false]])) {
    if (t < t0 || t > t1) continue;
    const xt = x(t);
    svg.append(el('line', { x1: xt, x2: xt, y1: m.t - 4, y2: H - m.b, class: 'moment' }));
    const close = xt - lastTop < 64;
    svg.append(el('text', { x: xt, y: close ? m.t + 12 : m.t - 10, class: 'moment-label halo', 'text-anchor': xt < m.l + 30 ? 'start' : xt > W - m.r - 30 ? 'end' : 'middle' }, name));
    if (!close) lastTop = xt;
    if (xt - lastBottom >= (withYear ? 70 : 44)) {
      svg.append(el('text', { x: xt, y: H - 10, class: 'tick', 'text-anchor': 'middle' }, withYear ? fmtDate(t) : dayMonth(t)));
      lastBottom = xt;
    }
  }
  if (x(launch) - m.l > 110) svg.append(el('text', { x: m.l, y: H - 10, class: 'tick' }, fmtDate(t0)));

  // Forecast: the straight line through the flight readings, carried on to the landing.
  if (opts.trend) {
    const a = Math.max(opts.trend.from, t0);
    if (a < trendEnd) svg.append(el('line', { x1: x(a), y1: y(opts.trend.at(a)), x2: x(trendEnd), y2: y(opts.trend.at(trendEnd)), class: 'trend' }));
  }

  // The readings: a 2px line per series. With few readings every reading gets a marker; with many,
  // only the readings outside the norm do, so the line stays readable.
  for (const s of seriesAll) {
    const pts = [...s.points].sort((p, q) => p.t - q.t);
    if (pts.length > 1 && !opts.ordinal) {
      svg.append(el('path', { d: pts.map((p, i) => `${i ? 'L' : 'M'}${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join(''), class: 'series-line', stroke: s.color, 'stroke-dasharray': s.dash || null }));
    }
    const sparse = pts.length <= 40;
    const ringAll = pts.length <= 60 || opts.ordinal;
    // With many readings, rings would pile up; the parts of the line outside the range are drawn thicker instead.
    if (!ringAll) {
      for (let i = 1; i < pts.length; i += 1) {
        if (pts[i].out && pts[i - 1].out) svg.append(el('line', { x1: x(pts[i - 1].t), y1: y(pts[i - 1].v), x2: x(pts[i].t), y2: y(pts[i].v), class: 'out-run' }));
      }
    }
    for (const p of pts) {
      if (p.out && (ringAll || p === pts[pts.length - 1])) svg.append(el('circle', { cx: x(p.t), cy: y(p.v), r: 5, class: 'dot out' }));
      else if (!p.out && (opts.ordinal || sparse)) svg.append(el('circle', { cx: x(p.t), cy: y(p.v), r: 3.5, class: 'dot', fill: s.color }));
    }
  }
  // With two lines (blood pressure), each is named on the chart, so colour is not needed to tell them apart.
  if (seriesAll.length > 1 && !opts.ordinal) {
    for (const s of seriesAll) {
      const pts = [...s.points].sort((p, q) => p.t - q.t);
      if (!pts.length) continue;
      const p0 = pts[0];
      svg.append(el('text', { x: Math.max(m.l + 4, x(p0.t) + 4), y: y(p0.v) + (s === seriesAll[0] ? -12 : 20), class: 'series-name halo' }, s.name.charAt(0).toUpperCase() + s.name.slice(1)));
    }
  }
  // The newest reading is named, so live and old readings are not confused.
  const firstSeries = seriesAll[0] ? [...seriesAll[0].points].sort((p, q) => p.t - q.t) : [];
  const newest = firstSeries[firstSeries.length - 1];
  if (newest && newest.t >= t0 && newest.t <= t1) {
    const nx = x(newest.t);
    svg.append(el('circle', { cx: nx, cy: y(newest.v), r: 4.5, class: newest.out ? 'dot out latest' : 'dot latest' }));
    svg.append(el('text', { x: nx > W - 90 ? nx - 8 : nx + 8, y: y(newest.v) - 9, class: 'tick latest-label halo', 'text-anchor': nx > W - 90 ? 'end' : 'start' }, 'Latest'));
  }

  // Names of the border lines: at the left, where the flight readings are not yet, on a halo. A name too long for
  // the chart is broken into lines once the chart is on the page (fitLabels), so its number and "(draft)" stay in view.
  const limitLabels = (opts.lines || []).map((l) => {
    const node = el('text', { x: m.l + 8, y: y(l.v) - 6, class: 'tick halo limit-label' }, l.label);
    svg.append(node);
    return { node, text: l.label, lineY: y(l.v) };
  });

  // Hover: a crosshair that snaps to the nearest reading in time, and a tooltip with every series.
  const cross = el('line', { y1: m.t, y2: H - m.b, class: 'crosshair', visibility: 'hidden' });
  svg.append(cross);
  const hit = el('rect', { x: m.l, y: m.t, width: W - m.l - m.r, height: H - m.t - m.b, fill: 'transparent', tabindex: 0 });
  svg.append(hit);
  const times = [...new Set(all.map((p) => p.t))].sort((a, b) => a - b);
  let focusIndex = times.length - 1;
  const show = (t) => {
    cross.setAttribute('x1', x(t));
    cross.setAttribute('x2', x(t));
    cross.setAttribute('visibility', 'visible');
    tip.replaceChildren();
    const head = document.createElement('div');
    head.className = 'tip-date';
    head.textContent = fmtGMT(t);
    tip.append(head);
    for (const s of seriesAll) {
      const p = s.points.find((q) => q.t === t);
      if (!p) continue;
      const row = document.createElement('div');
      row.className = 'tip-row';
      const key = document.createElement('span');
      key.className = s.dash ? 'tip-key dashed' : 'tip-key';
      key.style.borderTopColor = s.color;
      const val = document.createElement('strong');
      val.textContent = opts.ordinal ? opts.ordinal[p.v] : opts.fmt(p.v);
      const name = document.createElement('span');
      name.textContent = ` ${s.name}${outText ? (p.out ? `, ${outText}` : ', inside the normal range') : ''}`;
      row.append(key, val, name);
      tip.append(row);
    }
    tip.hidden = false;
    const box = host.getBoundingClientRect();
    tip.style.left = `${Math.min(Math.max(0, x(t) - 90), box.width - 200)}px`;
  };
  const nearest = (px) => {
    const t = t0 + ((px - m.l) / (W - m.l - m.r)) * (t1 - t0);
    let best = 0;
    for (let i = 1; i < times.length; i += 1) if (Math.abs(times[i] - t) < Math.abs(times[best] - t)) best = i;
    return best;
  };
  hit.addEventListener('pointermove', (ev) => {
    const r = svg.getBoundingClientRect();
    focusIndex = nearest(((ev.clientX - r.left) / r.width) * W);
    show(times[focusIndex]);
  });
  hit.addEventListener('pointerleave', () => { cross.setAttribute('visibility', 'hidden'); tip.hidden = true; });
  hit.addEventListener('focus', () => show(times[focusIndex]));
  hit.addEventListener('blur', () => { cross.setAttribute('visibility', 'hidden'); tip.hidden = true; });
  hit.addEventListener('keydown', (ev) => {
    if (ev.key === 'ArrowLeft') focusIndex = Math.max(0, focusIndex - 1);
    else if (ev.key === 'ArrowRight') focusIndex = Math.min(times.length - 1, focusIndex + 1);
    else return;
    ev.preventDefault();
    show(times[focusIndex]);
  });
  host.append(svg);
  fitLabels(limitLabels, { left: m.l + 8, right: W - m.r - 4, top: m.t });
  // "Latest" moves under its dot when a limit name sits where it would be.
  const latest = svg.querySelector('.latest-label');
  if (latest && limitLabels.some((lab) => overlaps(lab.node, latest))) latest.setAttribute('y', String(Number(latest.getAttribute('y')) + 27));
}

function overlaps(a, b) {
  try {
    const p = a.getBBox();
    const q = b.getBBox();
    return p.width > 0 && q.width > 0 && p.x < q.x + q.width && q.x < p.x + p.width && p.y < q.y + q.height && q.y < p.y + p.height;
  } catch { return false; }
}

// Breaks a text into lines at spaces so that no line is wider than maxWidth; measure(text) gives a width.
// A single word wider than the limit keeps a line of its own.
export function wrapWords(text, maxWidth, measure) {
  const lines = [];
  let line = '';
  for (const word of String(text ?? '').split(/\s+/).filter(Boolean)) {
    const next = line ? `${line} ${word}` : word;
    if (line && measure(next) > maxWidth) { lines.push(line); line = word; } else line = next;
  }
  if (line) lines.push(line);
  return lines;
}

// The limit names on a narrow chart: measured in the page (an estimate when there is no layout), wrapped into lines
// that end just above their dashed line, or start just below it when there is no room above.
const LABEL_LINE = 16;
function fitLabels(labels, { left, right, top }) {
  const width = right - left;
  for (const lab of labels) {
    const measure = (t) => {
      lab.node.textContent = t;
      let w = 0;
      try { w = lab.node.getComputedTextLength(); } catch { w = 0; }
      return w || String(t).length * 8.4; // 14 px mono text when nothing could be measured
    };
    const lines = measure(lab.text) > width ? wrapWords(lab.text, width, measure) : [lab.text];
    lab.node.textContent = '';
    if (lines.length === 1) { lab.node.textContent = lab.text; continue; }
    const above = lab.lineY - 6 - (lines.length - 1) * LABEL_LINE;
    const firstY = above - 12 >= top ? above : lab.lineY + LABEL_LINE;
    lab.node.setAttribute('y', String(firstY));
    lines.forEach((t, i) => lab.node.append(el('tspan', { x: left, dy: i ? LABEL_LINE : 0 }, t)));
  }
}

// The same readings as a table, so nothing depends on hovering.
export function drawTable(host, opts) {
  host.replaceChildren();
  const outText = opts.outText === undefined ? 'outside the normal range' : opts.outText;
  const table = document.createElement('table');
  const head = table.createTHead().insertRow();
  for (const name of ['Time', ...opts.series.map((s) => s.name)]) {
    const th = document.createElement('th');
    th.textContent = name;
    head.append(th);
  }
  const body = table.createTBody();
  const range = opts.range || null;
  const times = [...new Set(opts.series.flatMap((s) => s.points.map((p) => p.t)))]
    .filter((t) => !range || (t >= range.from && t <= range.to))
    .sort((a, b) => b - a);
  for (const t of times) {
    const row = body.insertRow();
    row.insertCell().textContent = fmtGMT(t);
    for (const s of opts.series) {
      const p = s.points.find((q) => q.t === t);
      row.insertCell().textContent = p ? `${opts.ordinal ? opts.ordinal[p.v] : opts.fmt(p.v)}${p.out && outText ? ` (${outText})` : ''}` : '';
    }
  }
  host.append(table);
}

// A small line for a tile: the last readings, the norm as a quiet band, the newest reading as a dot.
// opts: { points: [{ t, v, out }], band: { min, max } | null, label }
export function sparkline(host, opts) {
  host.replaceChildren();
  const pts = [...opts.points].filter((p) => Number.isFinite(p.v)).sort((a, b) => a.t - b.t);
  if (pts.length === 0) return;
  const W = Math.max(120, Math.round(host.getBoundingClientRect().width) || 200);
  const H = opts.height || 36;
  const pad = 4;
  let lo = Math.min(...pts.map((p) => p.v));
  let hi = Math.max(...pts.map((p) => p.v));
  const band = opts.band || null;
  if (band && band.min !== null && band.min !== undefined) lo = Math.min(lo, band.min);
  if (band && band.max !== null && band.max !== undefined) hi = Math.max(hi, band.max);
  if (hi - lo < 1e-9) { hi += 1; lo -= 1; }
  const spread = (hi - lo) * 0.1;
  lo -= spread;
  hi += spread;
  const t0 = pts[0].t;
  const t1 = pts[pts.length - 1].t > t0 ? pts[pts.length - 1].t : t0 + 1;
  const x = (t) => pad + ((t - t0) / (t1 - t0)) * (W - 2 * pad);
  const y = (v) => pad + (1 - (v - lo) / (hi - lo)) * (H - 2 * pad);
  const svg = el('svg', { viewBox: `0 0 ${W} ${H}`, width: '100%', height: H, class: 'spark', role: 'img', 'aria-label': opts.label || '' });
  if (band) {
    const top = band.max !== null && band.max !== undefined ? y(Math.min(band.max, hi)) : 0;
    const bottom = band.min !== null && band.min !== undefined ? y(Math.max(band.min, lo)) : H;
    if (bottom > top) svg.append(el('rect', { x: 0, y: top, width: W, height: bottom - top, class: 'spark-band' }));
  }
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join('');
  if (pts.length > 1) svg.append(el('path', { d: line, class: 'spark-line' }));
  for (const q of pts.slice(0, -1)) if (q.out) svg.append(el('circle', { cx: x(q.t), cy: y(q.v), r: 2.6, class: 'spark-out' }));
  const end = pts[pts.length - 1];
  svg.append(el('circle', { cx: x(end.t), cy: y(end.v), r: 3.2, class: end.out ? 'spark-end out' : 'spark-end' }));
  host.append(svg);
}
